  "inlineSchema": "// Prisma schema — SMK Jayanegara\n//\n// Target: PostgreSQL (Supabase, or any managed Postgres such as Neon).\n//\n// Prisma 7 moved the connection URL out of this file and into `prisma.config.ts`,\n// and moved the runtime connection to an explicit driver adapter. So the shape is:\n//\n//   prisma.config.ts     → CLI: migrations, db push, studio   (uses DIRECT_URL)\n//   src/lib/db.ts        → app: every query                   (uses DATABASE_URL)\n//\n// Two URLs, and the split matters on serverless: the app talks through the\n// pooled connection, migrations need a real session. On Vercel a pooled URL is\n// not an optimisation, it is what keeps the connection count sane.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// The single school profile row. `slug` is always \"utama\" so a lookup is\n/// unambiguous and the row can be upserted idempotently by the seed.\nmodel SchoolProfile {\n  id          String   @id @default(cuid())\n  slug        String   @unique @default(\"utama\")\n  schoolName  String   @default(\"SMK Jayanegara\")\n  tagline     String   @default(\"\")\n  heroLines   String[] @default([])\n  description String   @default(\"\")\n  history     String   @default(\"\")\n  vision      String   @default(\"\")\n  mission     String[] @default([])\n  address     String   @default(\"\")\n  city        String   @default(\"Mojokerto\")\n  province    String   @default(\"Jawa Timur\")\n  phone       String   @default(\"\")\n  whatsapp    String   @default(\"\")\n  email       String   @default(\"\")\n  instagram   String   @default(\"\")\n  youtube     String   @default(\"\")\n  mapsUrl     String   @default(\"\")\n  updatedAt   DateTime @updatedAt\n}\n\n/// A competency programme (jurusan), e.g. Desain Komunikasi Visual.\nmodel Program {\n  id               String   @id @default(cuid())\n  name             String\n  slug             String   @unique\n  shortDescription String   @default(\"\")\n  description      String   @default(\"\")\n  image            String   @default(\"\")\n  imagePublicId    String   @default(\"\")\n  features         String[] @default([])\n  order            Int      @default(0)\n  published        Boolean  @default(true)\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@index([published, order])\n}\n\n/// A news article. `slug` doubles as the public URL segment.\nmodel News {\n  id            String    @id @default(cuid())\n  title         String\n  slug          String    @unique\n  category      String    @default(\"Umum\")\n  excerpt       String    @default(\"\")\n  content       String    @default(\"\")\n  coverImage    String    @default(\"\")\n  coverPublicId String    @default(\"\")\n  published     Boolean   @default(false)\n  publishedAt   DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@index([published, publishedAt])\n}\n\n/// A gallery photo. `order` drives the editorial composition on the homepage.\nmodel GalleryItem {\n  id          String   @id @default(cuid())\n  title       String\n  image       String\n  publicId    String   @default(\"\")\n  category    String   @default(\"Umum\")\n  description String   @default(\"\")\n  order       Int      @default(0)\n  published   Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  @@index([published, order])\n}\n\n/// A dated school event.\nmodel Event {\n  id          String    @id @default(cuid())\n  title       String\n  slug        String    @unique\n  description String    @default(\"\")\n  image       String    @default(\"\")\n  publicId    String    @default(\"\")\n  date        DateTime\n  endDate     DateTime?\n  location    String    @default(\"\")\n  published   Boolean   @default(true)\n  createdAt   DateTime  @default(now())\n\n  @@index([published, date])\n}\n\n/// Work produced by students, shown in the exhibition section.\nmodel StudentWork {\n  id          String   @id @default(cuid())\n  title       String\n  studentName String   @default(\"\")\n  category    String   @default(\"Desain Komunikasi Visual\")\n  description String   @default(\"\")\n  image       String\n  publicId    String   @default(\"\")\n  year        Int?\n  order       Int      @default(0)\n  published   Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  @@index([published, order])\n}\n\n/// Editable copy for the fixed sections (hero, introduction, CTA, contact…).\n/// Keeping this in the database is what makes the homepage editable without a\n/// redeploy: the brief is explicit that copy must be changeable through the CMS.\nmodel SiteSection {\n  id        String   @id @default(cuid())\n  key       String   @unique\n  eyebrow   String   @default(\"\")\n  title     String   @default(\"\")\n  body      String   @default(\"\")\n  ctaLabel  String   @default(\"\")\n  ctaHref   String   @default(\"\")\n  updatedAt DateTime @updatedAt\n}\n",
